try {
  const body = $input.first().json.body || $input.first().json;
  const message = body?.message || body || {};
  const call = message.call || {};
  const analysis = message.analysis || {};
  const artifact = message.artifact || {};

  const vapiCallId = (call.id || body.call_id || '').trim();
  const callerNumber = (call.customer?.number || call.callerNumber || body.caller_number || '').trim();
  const duration = parseInt(call.endedAt && call.startedAt ? (new Date(call.endedAt) - new Date(call.startedAt)) / 1000 : (body.duration || 0));
  const transcript = artifact.transcript || body.transcript || '';
  const summary = analysis.summary || body.summary || '';
  const intent = analysis.structuredData?.intent || body.intent || 'diger';
  const callStatus = message.endedReason === 'assistant-error' ? 'failed' : 'completed';
  const recordingUrl = artifact.recordingUrl || body.recording_url || '';
  const cost = parseFloat(call.cost || body.cost || 0) || null;

  return [{ json: { vapiCallId, callerNumber, duration, transcript, summary, intent, callStatus, recordingUrl, cost, error: false } }];
} catch(e) {
  return [{ json: { error: true, message: String(e) } }];
}
